Moreover, we assume that in a neighborhood of $\xdag$,
	\begin{equation} \label{eq:nun}
		\norms{F[\x]-F_\n[\x]}_\Y \leq \rho_\n 
	\end{equation}
	holds locally uniformly.

Then, with the choice 
	\begin{equation*}
		\alpha \sim \delta, \; \eta \sim \delta^2 \,, \rho_{\n \xi} \sim \delta,
	\end{equation*}
    we obtain
    \begin{equation*}
        \norms{\x_{\n \xi}^{\alpha\delta\eta}-\xdag}_{L^2} = \mathcal{O}(\sqrt{\delta} + \xi)\;.
    \end{equation*}
